import { expect, test } from "vite-plus/test";
import * as NodeModule from "node:module";

// `message_keys` is generated by the Pebble build, so tests point require() at a stand-in.
const messageKeys = new URL("./message-keys.js", import.meta.url).href;
NodeModule.registerHooks({
  resolve: (specifier, context, nextResolve) =>
    specifier === "message_keys"
      ? { url: messageKeys, shortCircuit: true }
      : nextResolve(specifier, context),
});

test("speaks a new completed response only while its thread is focused", async () => {
  const handlers: Record<string, (event: any) => void> = {};
  const output: any[] = [];
  let poll: (() => void) | undefined;
  let item = { itemId: "old", type: "assistant_message", status: "completed", text: "old answer" };
  let speechCount = 0;
  const originalInterval = globalThis.setInterval;
  const originalClear = globalThis.clearInterval;
  const originalNow = Date.now;
  const now = Date.parse("2026-01-01T00:00:00.000Z");
  Date.now = () => now;
  globalThis.setInterval = ((callback: () => void) => {
    poll = callback;
    return 1;
  }) as typeof setInterval;
  globalThis.clearInterval = (() => {
    poll = undefined;
  }) as typeof clearInterval;
  (globalThis as any).localStorage = {
    getItem: (key: string) =>
      key === "mcpUrl"
        ? "https://test"
        : key === "mcpToken"
          ? "watch-test"
          : key === "elevenKey"
            ? "eleven-test"
            : null,
    setItem: () => {},
    removeItem: () => {},
  };
  (globalThis as any).Pebble = {
    addEventListener: (name: string, callback: (event: any) => void) => {
      handlers[name] = callback;
    },
    sendAppMessage: (message: any, success: () => void) => {
      output.push(message);
      success();
    },
  };
  (globalThis as any).XMLHttpRequest = class {
    status = 200;
    responseText = "";
    response: unknown;
    responseType = "";
    onload = () => {};
    onerror = () => {};
    method = "";
    path = "";
    body = "";
    open(method: string, url: string) {
      this.method = method;
      this.path = new URL(url).hostname === "api.elevenlabs.io" ? "/speech" : "/mcp";
    }
    setRequestHeader() {}
    getResponseHeader(name: string) {
      return name.toLowerCase() === "mcp-session-id"
        ? "session"
        : name.toLowerCase() === "content-type"
          ? this.responseType === "arraybuffer"
            ? "application/octet-stream"
            : "application/json"
          : null;
    }
    send(body: string) {
      this.body = body;
      if (this.path === "/speech") {
        speechCount++;
        this.response = new Uint8Array([1, 2]).buffer;
        return this.onload();
      }
      const request = JSON.parse(body);
      if (request.method === "notifications/initialized") {
        this.status = 202;
        this.responseText = "";
        return this.onload();
      }
      const result =
        request.method === "initialize"
          ? { protocolVersion: "2025-03-26" }
          : request.params.name === "t3_thread_list"
            ? {
                threads: [
                  {
                    threadId: "1",
                    title: "one",
                    projectId: "project",
                    providerInstanceId: "codex",
                    updatedAt: new Date(now - 14 * 3600000).toISOString(),
                  },
                ],
                nextCursor: null,
              }
            : request.params.name === "t3_environment_read"
              ? { label: "Mac" }
              : request.params.name === "t3_project_list"
                ? { projects: [{ id: "project", workspaceRoot: "/code/demo" }], nextCursor: null }
                : request.params.name === "t3_thread_read"
                  ? request.params.arguments.limit === 1
                    ? { thread: { itemCount: 1 }, items: [] }
                    : { items: [item] }
                  : { runId: "run" };
      this.responseText = JSON.stringify({ jsonrpc: "2.0", id: request.id, result });
      this.onload();
    }
  };
  try {
    await import("../src/pkjs/index.js");
    handlers.ready!({});
    expect(output.find((message) => message.action === "thread")).toMatchObject({
      machine: "Mac",
      directory: "demo",
      harness: "codex",
      age: "14h",
    });
    handlers.appmessage!({ payload: { action: "read", thread: "1" } });
    expect(speechCount).toBe(0);
    expect(
      output.some(
        (message) => message.action === "chat_item" && message.title === "assistant_message",
      ),
    ).toBe(true);
    item = { itemId: "new", type: "assistant_message", status: "running", text: "partial" };
    poll!();
    expect(speechCount).toBe(0);
    item = { ...item, status: "completed", text: "finished" };
    poll!();
    poll!();
    expect(speechCount).toBe(1);
    const start = output.find((message) => message.action === "audio_start");
    const packet = output.find((message) => message.action === "audio");
    expect(start.size).toBe(1);
    expect(packet[4]).toHaveLength(1);
    expect(start.checksum).toBe(Math.imul(2166136261 ^ packet[4][0], 16777619) >>> 0);
    handlers.appmessage!({ payload: { action: "audio_ack" } });
    expect(output.at(-1).action).toBe("audio_play");
    handlers.appmessage!({ payload: { action: "audio_retry" } });
    expect(output.filter((message) => message.action === "audio_start")).toHaveLength(2);
    handlers.appmessage!({ payload: { action: "close" } });
    expect(poll).toBeUndefined();
  } finally {
    Date.now = originalNow;
    globalThis.setInterval = originalInterval;
    globalThis.clearInterval = originalClear;
  }
});
